code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The repeated horizontal color strip gives the sequence of motif colors.
    palette = None
    for r in range(h):
        for end in range(r + 2, h + 1):
            if all(grid[i] == grid[r] for i in range(r + 1, end)):
                vals = [(c, grid[r][c]) for c in range(w) if grid[r][c] != 0]
                if len(vals) >= 2:
                    palette = [v for _, v in vals]
                    break
        if palette is not None:
            break
    if palette is None:
        return [row[:] for row in grid]

    # Find the connected component of color 1 that is the motif, excluding
    # the smaller color-1 strip component.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append(cells)
    motif = max(comps, key=len)
    r0, r1 = min(r for r,c in motif), max(r for r,c in motif)
    c0, c1 = min(c for r,c in motif), max(c for r,c in motif)
    shape = [(r-r0, c-c0) for r,c in motif]
    mh = r1-r0+1
    # Locate the seed color in the palette and keep its original vertical slot.
    idx = palette.index(1)
    start = r0 - idx*mh
    out = [[0]*w for _ in range(h)]
    for i, color in enumerate(palette):
        top = start + i*mh
        for dy, dx in shape:
            y, x = top+dy, c0+dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out
'''
